-- Prerequisite check for the "Classify uploads with an LLM" course. GENERATED by
-- samples/generate_load_script.py. Run in SQLcl or SQL*Plus, connected as the ADM schema owner:
--
--   @00_precheck.sql
--
-- Five checks, each with the fix for a failure. Check 5 sends one small PDF to the model, so it
-- uses a few hundred tokens. It changes no data.

-- @dblinter ignore(g-5010): a tutorial script prints its results with dbms_output on
-- purpose, so the reader sees them directly in SQLcl.

-- The provider, the model and the web credential that the course uses. To use others, change
-- the first three lines here and the three constants c_provider, c_model and c_credential in
-- 02_hkd_ai_api.pks. The model-comparison script 02_model_check.sql has its own list of models.
define hkd_provider   = openai
define hkd_model      = gpt-6.1-sol
define hkd_credential = OPENAI
define hkd_user       = ADMIN

set define on
set verify off
set serveroutput on
set feedback off

prompt
prompt ==========================================================
prompt  Classify uploads with an LLM - prerequisite check
prompt ==========================================================
prompt

-- ---------------------------------------------------------------------------
-- 1. The finished hooks demo is installed
-- ---------------------------------------------------------------------------
declare
  l_count number;
  l_cols  number;
begin
  select count(*)
    into l_count
    from user_objects
   where object_type = 'PACKAGE BODY'
     and object_name in ('HKD_HOOK_API', 'HKD_WORKER_API')
     and status = 'VALID';

  select case when exists (
           select 1
             from user_tab_columns c
            where c.table_name  = 'HKD_WORKFLOWS'
              and c.column_name = 'HANDLER'
         ) then 1 else 0 end
    into l_cols
    from dual;

  if l_count < 2 or l_cols = 0 then
    sys.dbms_output.put_line('1. FAILED: the hooks demo is missing or too old.');
    sys.dbms_output.put_line('   Fix: run ../db/install.sql. It installs the finished demo in one step.');
    return;
  end if;

  select count(*)
    into l_count
    from adm_hooks
   where hook_key in ('AFTER_NEW_FILE_UPLOAD', 'AFTER_NEW_FILE_VERSION')
     and hook_plsql like 'hkd_hook_api.%';

  if l_count < 2 then
    sys.dbms_output.put_line('1. FAILED: the upload and version hooks are not registered.');
    sys.dbms_output.put_line('   Fix: run ../db/install.sql.');
  else
    sys.dbms_output.put_line('1. The hooks demo is installed and both file hooks are registered.');
  end if;
end;
/

-- ---------------------------------------------------------------------------
-- 2. The ADM user exists
-- ---------------------------------------------------------------------------
declare
  l_exists number;
begin
  select case when exists (
           select 1
             from adm_users u
            where upper(u.username) = upper('&hkd_user')
         ) then 1 else 0 end
    into l_exists
    from dual;

  if l_exists = 0 then
    sys.dbms_output.put_line('2. FAILED: there is no ADM user named &hkd_user.');
    sys.dbms_output.put_line('   Fix: add the user with adm_user_api.add_user (see the ADM installation guide),');
    sys.dbms_output.put_line('   or change hkd_user at the top of this script and in every script of the course.');
  else
    sys.dbms_output.put_line('2. The ADM user &hkd_user exists.');
  end if;
end;
/

-- ---------------------------------------------------------------------------
-- 3. UC AI is installed
-- ---------------------------------------------------------------------------
declare
  l_version varchar2(16 char);
  c_probe   constant varchar2(100 char) := 'begin :1 := uc_ai.c_version; end;';
begin
  -- Dynamic on purpose, so this script still runs and reports when UC AI is not installed.
  execute immediate c_probe using out l_version;
  sys.dbms_output.put_line('3. UC AI is installed. Version ' || l_version || '.');
exception
  when others then
    sys.dbms_output.put_line('3. FAILED: UC AI is not installed in this schema.');
    sys.dbms_output.put_line('   Fix: install the AI Pack (install_ai.sql). See the AI Pack installation guide.');
end;
/

-- ---------------------------------------------------------------------------
-- 4. The web credential exists
-- ---------------------------------------------------------------------------
declare
  l_exists number;
begin
  select case when exists (
           select 1
             from apex_workspace_credentials c
            where c.static_id = '&hkd_credential'
         ) then 1 else 0 end
    into l_exists
    from dual;

  if l_exists = 0 then
    sys.dbms_output.put_line('4. FAILED: no APEX web credential with the static id &hkd_credential is visible to this schema.');
    sys.dbms_output.put_line('   Fix: in APEX go to Workspace Utilities > Web Credentials and create one named &hkd_credential');
    sys.dbms_output.put_line('   (type HTTP Header, header Authorization, value "Bearer <your key>").');
    sys.dbms_output.put_line('   Another name works too: change hkd_credential at the top of this script and c_credential in 02_hkd_ai_api.pks.');
  else
    sys.dbms_output.put_line('4. The web credential &hkd_credential exists.');
  end if;
end;
/

-- ---------------------------------------------------------------------------
-- 5. The model can read a PDF
-- ---------------------------------------------------------------------------
declare
  l_b64      clob;
  l_content  json_array_t := json_array_t();
  l_messages json_array_t := json_array_t();
  l_result   json_object_t;
  l_workspace apex_workspaces.workspace%type;
begin
  sys.dbms_lob.createtemporary(l_b64, true);
  sys.dbms_lob.append(l_b64, '');
  sys.dbms_lob.append(l_b64, '');
  l_content.append(uc_ai_message_api.create_file_content(
    p_media_type => 'application/pdf'
  , p_data_blob  => apex_web_service.clobbase642blob(l_b64)
  , p_filename   => 'check.pdf'
  ));
  l_content.append(uc_ai_message_api.create_text_content('What is the title of this document? Reply with the title only.'));
  l_messages.append(uc_ai_message_api.create_user_message(l_content));

  -- The web credential belongs to a workspace, so the call needs one.
  select min(workspace)
    into l_workspace
    from apex_workspaces
   where workspace != 'INTERNAL';
  apex_util.set_workspace(l_workspace);

  l_result := uc_ai.generate_text(
    p_messages => l_messages
  , p_provider => '&hkd_provider'
  , p_model    => '&hkd_model'
  , p_config   => json_object_t('{"g_apex_web_credential":"&hkd_credential"}')
  );

  sys.dbms_output.put_line('5. The model read the PDF: "' || substr(l_result.get_clob('final_message'), 1, 60) || '"');
  sys.dbms_output.put_line('   Tokens used: ' || l_result.get_object('usage').get_number('total_tokens') || '. Workspace used: ' || l_workspace || '.');
exception
  when others then
    sys.dbms_output.put_line('5. FAILED: the call to the model did not work.');
    sys.dbms_output.put_line('   Error: ' || substr(sqlerrm, 1, 300)); -- @dblinter ignore(g-5080): the message is the diagnosis this check exists to give, a backtrace of a probe would only confuse the reader
    sys.dbms_output.put_line('   ORA-24247  no network ACL: a DBA must allow this schema to reach api.openai.com on port 443.');
    sys.dbms_output.put_line('   ORA-29024  certificate not trusted: the OpenAI certificate chain must be in the database wallet.');
    sys.dbms_output.put_line('   ORA-01403  the web credential was not found in the workspace this session uses.');
    sys.dbms_output.put_line('   HTTP 401   the key in the web credential is wrong or has expired.');
    sys.dbms_output.put_line('   HTTP 404   the key has no access to the model &hkd_model.');
end;
/

prompt
prompt If none of the five lines says FAILED, install the course objects with install.sql.
